```cpp
server_prompt_cache_state * server_prompt_cache::alloc(const server_prompt & prompt, ...) {
    // skip if already cached
    for (auto it = states.begin(); it != states.end(); ++it) {
        const int cur_lcp_len = it->prompt.tokens.get_common_prefix(prompt.tokens);
        if (cur_lcp_len == (int) prompt.tokens.size()) {
            return nullptr; // already in cache
        }
    }

    // remove obsolete entries fully contained in the new prompt
    for (auto it = states.begin(); it != states.end();) {
        const int len = it->prompt.tokens.get_common_prefix(prompt.tokens);
        if (len == (int) it->prompt.tokens.size()) {
            it = states.erase(it);
        } else { ++it; }
    }

    // evict oldest if over size limit
    while (!states.empty() && size() + state_size_new > limit_size) {
        states.pop_front();
    }
    // ... push new state ...
}
```

### `load()` — Find the best cached prompt for a new task
```cpp
bool server_prompt_cache::load(server_prompt & prompt, const server_tokens & tokens_new, ...) {
    // baseline: the slot's current prompt
    const int lcp_best = prompt.tokens.get_common_prefix(tokens_new);
    float f_keep_best = prompt.tokens.size() > 0
        ? float(lcp_best) / prompt.tokens.size() : -1.0f;
    float sim_best = float(lcp_best) / tokens_new.size();

    // search all cached states for a better match
    for (auto it = states.begin(); it != states.end(); ++it) {
        const int lcp_cur = it->prompt.tokens.get_common_prefix(tokens_new);
        const float f_keep_cur = float(lcp_cur) / it->prompt.tokens.size();
        const float sim_cur = float(lcp_cur) / tokens_new.size();

        // don't trash large prompts — f_keep must be >= 25%
        if (f_keep_cur < 0.25f) continue;

        // must improve BOTH f_keep and sim over baseline
        if (f_keep_best < f_keep_cur && sim_best < sim_cur) {
            f_keep_best = f_keep_cur;
            sim_best = sim_cur;
            it_best = it;
        }
    }

    if (it_best != states.end()) {
        // restore KV cache state into llama context
        llama_state_seq_set_data_ext(ctx_tgt, data.data(), size, id_slot, 0);
        prompt = std::move(it_best->prompt);
        states.erase(it_best);
    }
    return true;
}
```

